#include <numeric>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long k;
    long long w;
    cin >> n >> k >> w;
    vector<long long> profit(n);
    for (int i = 0; i < n; i++) cin >> profit[i];
    vector<long long> cap(n);
    for (int i = 0; i < n; i++) cin >> cap[i];

    vector<int> order(n);
    for (int i = 0; i < n; i++) order[i] = i;
    sort(order.begin(), order.end(), [&](int x, int y) { return cap[x] < cap[y]; });
    priority_queue<long long> heap;
    int j = 0;
    for (long long step = 0; step < k; step++) {
        while (j < n && cap[order[j]] <= w) {
            heap.push(profit[order[j]]);
            j++;
        }
        if (heap.empty()) break;
        w += heap.top();
        heap.pop();
    }
    cout << w << "\n";

    return 0;
}

