import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long k = Long.parseLong(next());
        long w = Long.parseLong(next());
        long[] profit = new long[(int) n];
        for (int i = 0; i < profit.length; i++) profit[i] = Long.parseLong(next());
        long[] cap = new long[(int) n];
        for (int i = 0; i < cap.length; i++) cap[i] = Long.parseLong(next());

        int count = (int) n;
        Integer[] order = new Integer[count];
        for (int i = 0; i < count; i++) order[i] = i;
        Arrays.sort(order, (x, y) -> Long.compare(cap[x], cap[y]));
        PriorityQueue<Long> heap = new PriorityQueue<>(Collections.reverseOrder());
        int j = 0;
        for (long step = 0; step < k; step++) {
            while (j < count && cap[order[j]] <= w) {
                heap.add(profit[order[j]]);
                j++;
            }
            if (heap.isEmpty()) break;
            w += heap.poll();
        }
        System.out.println(w);
    }
}
